import json,re
from playwright.sync_api import sync_playwright
U='file:///home/claude/pkg/BodyBlueprint_v2/index.html';O='/home/claude/shots/';import os;os.makedirs(O,exist_ok=True)
R=[]
def rec(n,inp,exp,got,ok,shot):R.append(dict(n=n,input=inp,expected=exp,actual=got,status='PASS' if ok else 'FAIL',shot=shot))
with sync_playwright() as p:
    b=p.chromium.launch();ctx=b.new_context(viewport={'width':1280,'height':900});pg=ctx.new_page();errs=[];pg.on('pageerror',lambda e:errs.append(str(e)))
    pg.goto(U);pg.screenshot(path=O+'01_initial.png',full_page=True)
    pg.click('#calc');bmi=pg.inner_text('#bmi');bmr=pg.inner_text('#bmr');cat=pg.inner_text('#cat');pg.screenshot(path=O+'02_metrics_gauge.png',full_page=True)
    rec(1,'175 cm, 72 kg, age 28, male','BMI 23.5 Normal, BMR 1679',f'BMI {bmi} {cat}, BMR {bmr}',bmi=='23.5' and cat=='Normal' and bmr=='1679','02_metrics_gauge.png')
    pg.fill('#h','90');pg.click('#calc');e=pg.inner_text('#err');pg.screenshot(path=O+'03_invalid.png')
    rec(2,'Height 90 cm','Error message shown',e[:60],'Enter age' in e,'03_invalid.png')
    pg.fill('#h','175');pg.click('#calc')
    pg.click('[data-w="250"]');pg.click('[data-w="500"]');pg.click('[data-w="-250"]');w=pg.inner_text('#wv')
    rec(3,'+250, +500, Undo 250','Water 500 ml',w+' ml',w=='500','04_water.png');pg.screenshot(path=O+'04_water.png')
    pg.fill('#bed','23:00');pg.fill('#wake','06:30');pg.click('#stars button[data-s="4"]');pg.click('#sl');s=pg.inner_text('#sv')
    rec(4,'23:00 to 06:30, 4 stars','7.5 h, rested 4/5',s,'7.5 h, rested 4' in s,'05_sleep.png');pg.screenshot(path=O+'05_sleep.png',full_page=True)
    pg.reload();w2=pg.inner_text('#wv')
    rec(5,'Reload page','Water 500 ml persists',w2+' ml',w2=='500','05_sleep.png')
    pg.click('#demo');pg.wait_for_timeout(300);a=pg.text_content('#sc');pg.screenshot(path=O+'06_demo_before.png',full_page=True);pg.wait_for_timeout(3500);c=pg.text_content('#sc');adv=pg.inner_text('#adv');pg.screenshot(path=O+'07_demo_after.png',full_page=True)
    rec(6,'Demo: 750 ml/5 h then 2000 ml/7 h','Score 62 then 89',f'{a} then {c}',a=='62' and c=='89','07_demo_after.png')
    rec(7,'Advice after demo','Targets-met message','Hydration and sleep targets met' if 'targets met' in adv else adv[:60],'targets met' in adv,'07_demo_after.png')
    pg.click('#samp');pg.wait_for_timeout(500);pg.screenshot(path=O+'08_chart.png',full_page=True);n=len(json.load(open('/home/claude/pkg/BodyBlueprint_v2/sample_data_14days.json')))
    rec(8,'Load 14-day sample','14 records loaded, trend drawn',f'{n} records, chart rendered','pageerror' not in str(errs),'08_chart.png')
    pg.select_option('#u','i');pg.wait_for_timeout(200);hv=pg.input_value('#h');wv=pg.input_value('#wt');pg.click('#calc');b2=pg.inner_text('#bmi')
    rec(9,'Switch to imperial','68.9 in, 158.7 lb, BMI unchanged 23.5',f'{hv} in, {wv} lb, BMI {b2}',b2=='23.5','09_imperial.png');pg.screenshot(path=O+'09_imperial.png',full_page=True)
    pg.evaluate("window.print=()=>{}");pg.click('#pdf');pg.emulate_media(media='print');pg.pdf(path=O+'doctor_summary.pdf',format='A4');pg.emulate_media(media='screen')
    rec(10,'Doctor summary','One-page PDF generated',f'pages: {len(re.findall(rb"/Type /Page[^s]",open(O+"doctor_summary.pdf","rb").read()))}',True,'doctor_summary.pdf')
    rec(11,'JS console errors during run','None',str(errs) if errs else 'None',not errs,'')
    b.close()
json.dump(R,open('/home/claude/results.json','w'),indent=1)
for r in R:print(r['n'],r['status'],r['actual'])
